// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        // Get the original admin and owner
        address admin = c.owner(); // initially msg.sender, the test contract deployer
        // The reference admin is the deployer of c (this contract in setUp);
        // The buggy modifier compares against owner instead of admin.
        // If actor is the current owner (but not admin), the bug allows changing owner.
        // We let the fuzzer choose any actor and newOwner.

        // Record current owner before the call
        address currentOwner = c.owner();

        vm.prank(actor);
        try c.setOwner(newOwner) {
            // succeeded
        } catch {
            // reverted
        }

        // After the call, if actor is the original admin (deployer), reference updates owner.
        // If actor is the current owner (but not admin), reference reverts, bug updates owner.
        // The rule: after any call to setOwner from any actor, if the actor is not the original admin,
        // the owner must remain unchanged.
        address finalOwner = c.owner();
        bool unchangedIfNotAdmin = (actor != admin) ? (finalOwner == currentOwner) : true;
        assertTrue(unchangedIfNotAdmin);
    }
}

