pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        try c.setOwner(newOwner) {} catch {}
        address afterCall = c.owner();
        vm.prank(actor);
        try c.setOwner(address(0xdead)) {} catch {}
        address afterSecondCall = c.owner();
        bool unchangedBySecondCall = (afterCall != address(0xdead)) ? (afterSecondCall == afterCall) : true;
        assertTrue(unchangedBySecondCall || afterSecondCall == address(0xdead));
    }
}

