// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonAdmin, address newOwner) public {
        vm.assume(nonAdmin != address(this));
        // Record owner before the call
        address ownerBefore = c.owner();
        vm.prank(nonAdmin);
        bool success = c.setOwner(newOwner);
        // The reference returns false (revert) for non-admin, so owner stays unchanged.
        // The bug returns true and changes the owner.
        if (nonAdmin == c.owner()) {
            // In the reference, a non-admin can never become the owner.
            assertTrue(success == false);
        } else {
            // In the reference, the owner never changes, so success must be false.
            assertTrue(success == false);
        }
    }
}

